"""Seal measured native SF2 plumbing evidence; never infer successful gates."""
import json,hashlib,subprocess
from pathlib import Path
from qualify_native_sf2_manifest import OUT

ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((OUT/name).read_text())
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def run():
    result=read('fresh/SCIENTIFIC_COMPARISON.json');audit=read('fresh/FINAL_NATIVE_AUDIT.json')
    assert result['passed'] and audit['certificate']['active']==56462864
    manifest=read('NATIVE_MANIFEST_AUDIT.json');performance=read('PERFORMANCE.json');execution=performance['execution']
    tests=read('TESTS.json');memory=read('MEMORY_COMPONENTS.json');cohort=[read(f'LAYER_{k:02}_PREQUALIFICATION.json') for k in (1,5,11,12,20)]
    assert all(r['native_state'] and r['restart_exact'] for r in cohort)
    assert read('ATLAS_FULL_EQUIVALENCE.json')['passed'] and read('FORECAST_FULL_EQUIVALENCE.json')['passed']
    repairs=read('IMPLEMENTATION_REPAIRS.json');archive=read('ARCHIVE.json')
    prior=ROOT/'results/native_mixed_production_migration'
    assert sha(prior/'report.md')=='6fceb128673af3e89433d56d8e50bc22168eaee5ee7e8b75dcdc4212b362dca4'
    assert sha(prior/'AUTHORITY.json')=='8f6f00c73cf4d24c573e461d5030972598e72d75d6b35c0a4275b008b38a5c7e'
    sections=[]
    def add(title,text):sections.append('### '+title+'\n\n'+text+'\n')
    add('A. Authority verification','Starting HEAD: `07db5f96bc3556d6ccbd721a4862e57320a81a69`. Branch: `feature/sdf-cfd-mesher-v4-advancing-front`. The prior report and authority match the user-supplied SHA-256 values. Prior evidence remains sealed. No V3 source was edited. The pre-existing untracked V3 directory and 155 unrelated dirty status entries remain outside this commit.')
    add('B. Starting blockers','Implemented all four missing paths: native prism import, native Task-4C atlas, native future forecast, and compact native SF2 proof binding. No geometry, correction, trigger, capacity, or certificate algorithm was added. Hard gates are unchanged.')
    add('C. Native prism checkpoint import','Layers 1, 5, 11, 12, and 20 instantiate real native mixed checkpoints. Immutable NumPy-backed entity mappings expose source-keyed vertices, cells, faces, columns, prism front, and outer interface without expanding millions of Python dictionaries. Wall/source ancestry, schedule, quality ranges, atlas, forecast, and certificate blocks are native checkpoint components. Ordinary columns remain active; no termination or remesh history is invented.')
    add('D. Legacy-state release','The legacy CommitStore exists only during historical import. The providers retain no legacy store. Immutable mmap backing is shared by native entity views. Layer-20 RSS falls from 224,104,448 to 189,915,136 bytes after legacy variables are released. Cohort peak RSS is '+str(max(r['peak_rss'] for r in cohort))+' bytes. Sparse transaction overlays preserve private rollback without copying the full regular prism block.')
    add('E. Native risk atlas','NativeRiskAtlas consumes the native active front, outer interface, schedule, source ancestry, topology/geometry versions and forecast dependencies. It uses the unchanged qualified Task-4C rules. All 20 freshly generated atlas state/generation/evaluation arrays and scientific hashes equal preserved SF2. Pre-correction partitions also match: layer 11 remains active and layer 12 becomes passive. Layers 12–20 have no active correction region. Imported post-layer-11 state is already passive after its final correction; this is not the pre-correction active fraction. See ATLAS_FULL_EQUIVALENCE.json.')
    add('F. Native future forecast','NativeForecast consumes native immutable arrays and explicit active column membership. All 20 fresh projected coordinate and normal buffers equal the preserved forecast bit-for-bit. Five imported checkpoints reproduce native descriptors, dependencies, warning state and restart identity. Cache identity binds source ancestry, schedule, local current layer, topology and geometry versions. The existing mixed trajectory projector handles adjusted schedules and emits zero prism futures for terminated columns; transition outer faces remain screening inputs. The stored binary64 schedule is reused, never reconstructed from rounded decimal inputs.')
    add('G. Compact SF2 certificate manifest',f'Imported {manifest["active"]:,} relations, recomputed 0. Native disk-owned relation blocks bind packed indices to source-edge scientific identities, layer ownership, geometry, proof class, witness and outcome hashes. The production validator audits this native manifest. Expected/active: 56,462,864/56,462,864; missing/duplicate/forbidden/unresolved: 0/0/0/0. Fresh construction independently generated the same complete relation identities. Retry after proof publication is idempotent; changed or corrupted retry evidence is rejected.')
    add('H. Manifest memory model',f'Native proof storage: {manifest["disk_bytes"]:,} bytes. Index payload: {memory["manifest_index_payload_bytes"]:,} bytes. The empty measurement process used 70,815,744 bytes; loading the index used 70,995,968 bytes. After 100 scientific lookups RSS was 71,634,944 bytes. Mean lookup: {memory["mean_lookup_seconds"]:.6f} s. No expanded 56.46-million-relation object graph exists. Import plus source verification peak: {manifest["peak_rss"]:,} bytes. Native complete coverage audit: {manifest["audit_seconds"]:.3f} s. Witness payloads stay compressed on disk.')
    for label,row in zip(('I. SF2 layer-1 prequalification','J. SF2 layer-5 prequalification','K. SF2 layer-11 prequalification','L. SF2 layer-12 prequalification','M. SF2 layer-20 prequalification'),cohort):
        add(label,f'PASS. {row["audit"]["cells"]:,} native cells. Exact wall, first layer, prism/front coordinates, topology/source ancestry, atlas, forecast, quality and certificate binding. Deterministic native checkpoint restart passes. Zero remesh triggers. Import {row["import_seconds"]:.3f} s; measured process peak {row["peak_rss"]:,} bytes; restart RSS {row["restart_rss"]:,} bytes. Detailed evidence: LAYER_{row["layer"]:02}_PREQUALIFICATION.json.')
    add('N. Native layer-20 final audit','PASS. All 20 layer-range quality receipts cover 2,126,040 cells and their required faces. Native input identities verify coordinates, connectivity, schedule, SDF authority and conditioning arrays. Native topology ownership and full certificate coverage pass. The final wall hash is `'+audit['wall']+'`; first-layer hash is `'+audit['first_layer']+'`. Both match preserved SF2 exactly.')
    add('O. Fresh full SF2 native build','PASS. Started from authoritative layer 0 and committed all 20 layers through MixedFrontRunner. Construction used native state and existing numerical kernels with an explicit native context. No legacy CommitStore and no accepted reference correction coordinates drove construction. The old reference was opened only after the fresh native final audit. Result: 2,126,040 wall prisms; zero termination regions; zero remesh events. Exact checkpoints survive all comparison/revalidation work.')
    differences=sum(len(r['transient_conditioning_differences']) for r in result['correction_history'])
    add('P. SF2 scientific equality',f'PASS for all committed coordinates, connectivity/source ownership, correction decisions, hard-metric arrays, final conditioning arrays, forecast/atlas states, and certificate pair/outcome identities. A runtime defect was repaired: NumPy 2.4.0 changed LAPACK conditioning rounding relative to the installed qualified NumPy 1.26.4 runtime. All 20 diagnostic receipts were regenerated from fresh coordinates under NumPy 1.26.4 in {repairs["seconds"]:.3f} s. No reference numerical values were copied; no geometry or exact proofs changed. Native construction now rejects an unqualified NumPy version. {differences} descriptive sigma/G_bound extrema on historical search trials still record their original runtime values. These are explicitly retained as transient differences, not hidden or made hard gates. Every hard decision and all final conditioning arrays compare exactly. The comparator rejects changes to hard-gate values.')
    stages=performance['stages']
    add('Q. Runtime',f'Total charged scientific execution: {execution["scientific_seconds"]:.3f} s ({execution["scientific_seconds"]/60:.2f} min), including runtime diagnosis, receipt repair and after-the-fact comparisons. This is {performance["overhead_seconds"]:.3f} s ({performance["overhead_percent"]:.2f}%) above 1,248.01 s. The 1,800 s cap was not reached. Initial scan: {performance["initial"]["total_seconds"]:.3f} s, including forecast {performance["initial"]["forecast_seconds"]:.3f} s. Across commits: preparation {stages["prepare_seconds"]:.3f} s; numerical validation {stages["numeric_seconds"]:.3f} s (including exact Jacobians {stages["exact_sign_seconds"]:.3f} s); immediate certification {stages["certificate_seconds"]:.3f} s; state rebuilding {stages["state_seconds"]:.3f} s. Detailed metrics, atlas and future spot checks are included in preparation, not separately timed in this run. Remaining wall time includes checkpoint publication, native-state validation, final audits and comparison. No invented per-kernel timing split is reported.')
    add('R. Peak RSS',f'Fresh aggregate process-tree peak: {execution["peak_tree_rss"]:,} bytes. Legacy baseline: 1,540,079,616 bytes. This is a material increase; the full-run memory issue is not declared solved. Separate native component probe: restart 163,643,392 bytes; forecast 265,969,664 bytes; atlas with shared forecast 272,211,968 bytes. Native import releases legacy objects, entity views share array backing, proof storage is disk-backed, and comparison avoids deep copies of trial proof graphs. The full-run peak was not sampled by every kernel, so its dominant transient cannot be attributed precisely. This remains a performance follow-up, not a weakened acceptance gate.')
    add('S. Production authority','YES. `authorities/PRODUCTION_RUNNER.json` binds the successful comparison hash. Default Task-4 production dispatch selects the native MixedFrontRunner; the old implementation remains explicit `--legacy-reference` replay only. The same mixed state/journal model handles regular prism blocks and existing sparse mixed geometry. Use the installed Python 3.12 / NumPy 1.26.4 runtime. No second legacy production state is retained.')
    add('T. Automatic remesh default','ENABLED for the native mixed runner and its already-qualified geometry providers. Existing policy and remesh science are unchanged. The switch also verifies the preserved native general-SDF rollback authority: 45 committed layer-4 prisms and 2 layer-5 tetrahedra removed, 7,604 final cells, 538,033 valid relations. That expensive geometry run was not repeated. Current mixed transaction/recovery, adjusted schedule and terminated-column tests pass; SF2 produced zero false remesh events.')
    add('U. Determinism','Five native checkpoint round-trips reproduce scientific state, atlas and forecast exactly. Fresh full geometry, accepted decisions and scientific certificate identities equal the sealed independent production result. Source-keyed maps and immutable proof blocks survive restart; sparse rollback does not mutate committed backing. Storage shape/dtype collisions and manifest replay after an interrupted publication have focused regression coverage. The numerical runtime is now explicit; bitwise conditioning portability across arbitrary BLAS/NumPy builds is not claimed.')
    add('V. Tests',f'{tests["passed"]} passed, 0 failed in {tests["seconds"]:.2f} s. Command and nine test files are in TESTS.json. Coverage includes native imports, atlas/forecast, compact manifest lookup/retry, checkpoint/recovery, mixed topology, schedules, policy, rolling behavior and certificate adapters. A test-only ambiguous module import was corrected. `git -c core.whitespace=cr-at-eol diff --cached --check` passes. CRLF evidence bytes are preserved. Existing scientific implementations and V3 were not edited.')
    add('W. Classification','**V4NativeSF2ProductionPlumbingQualified**. All four implementation blockers are completed, all five bounded checkpoints pass, and the fresh full native shell passes final scientific qualification. The measured RSS increase remains an explicit limitation.')
    add('X. Recommended next task','Production native-runner memory profiling and reduction, followed by full transition-to-core integration. Do not change meshing science to optimize memory. Core integration was not started here. The complete checkpoint/proof evidence is losslessly archived in EVIDENCE.tar.zst parts with per-file hashes and a verified restoration utility.')
    report='## Decision question\n\nCan V4 finish the four missing native production components, pass bounded SF2 equivalence, and run the qualified SF2 shell through the native mixed-front runner without relying on legacy production authority?\n\n'+'\n'.join(sections)
    (OUT/'report.md').write_text(report,encoding='utf8')
    files=subprocess.check_output(['git','-c','core.longpaths=true','ls-files','--modified','--others','--exclude-standard','--','research/sdf_cfd_mesher_v4'],text=True).splitlines()
    files=sorted(set(files+subprocess.check_output(['git','-c','core.longpaths=true','diff','--cached','--name-only','--','research/sdf_cfd_mesher_v4'],text=True).splitlines()))
    source={p.replace('\\','/'):sha(Path(p)) for p in files if Path(p).is_file() and '/results/' not in p.replace('\\','/')}
    evidence={p.name:sha(p) for p in OUT.glob('*.json') if p.name!='AUTHORITY.json'}
    authority=dict(task='FinishV4NativeSF2ProductionPlumbing',classification='V4NativeSF2ProductionPlumbingQualified',
        starting_head='07db5f96bc3556d6ccbd721a4862e57320a81a69',report_sha256=sha(OUT/'report.md'),sources=source,evidence=evidence,
        fresh_comparison_sha256=sha(OUT/'fresh/SCIENTIFIC_COMPARISON.json'),production_authority=True,automatic_remesh=True,
        v3_task_modifications=0,scientific_requirements_changed=False,tests=tests['passed'],archive_sha256=archive['sha256'])
    (OUT/'AUTHORITY.json').write_text(json.dumps(authority,sort_keys=True,indent=2)+'\n')
    (OUT/'SHA256SUMS.txt').write_text('\n'.join(sha(OUT/name)+'  '+name for name in ('report.md','AUTHORITY.json'))+'\n')
    print((OUT/'SHA256SUMS.txt').read_text())

if __name__=='__main__':run()
